"explanation": "元金均等返済は毎回の元金返済額が一定であるため、返済当初は残元金が多く利息負担が大きいことから、当初の返済額は元利均等返済より多くなる。しかし残元金の減少が早いため利息の累積が少なく、総返済額は元金均等返済の方が少なくなる。\n\nA：誤り。元利均等返済は毎回の返済額が一定だが、返済初期ほど利息の割合が高く（元金比率が低く）、返済が進むにつれて元金比率が高くなる（利息比率が低くなる）。\nC：誤り。同じ条件なら総返済額は「元利均等返済の方が多く」なる。元金均等返済の方が総返済額が少ない。\nD：誤り。フラット35は全期間固定金利型であることは正しいが、融資実行時の金利が固定されるため「借入期間中に金利が変動しない」点は正しい。ただし「毎回の返済額が一定」は元利均等返済の場合のみ。フラット35自体は元利均等返済が基本だが、「全期間固定かつ毎回返済額一定」が正しい記述となるため本選択肢は正しい。\n\n本問の正解はB（選択肢index=1）。\n\n【頻出】元利均等と元金均等の比較（当初返済額・総返済額）は必出論点。\n【混同注意】「総返済額が少ない＝元金均等」「毎月返済額が一定＝元利均等」を対比で整理。"
