"explanation": "学生納付特例制度は、在学中の学生が申請により保険料の納付を猶予される制度。猶予期間は受給資格期間（10年）には算入されるが、追納しない場合は老齢基礎年金の年金額には反映されない（国民年金法第90条の3）。\n\nB：誤り。全額免除期間は年金額の計算上2分の1（2009年4月以降）として扱われる。4分の1は「4分の1納付（4分の3免除）」の場合の取扱いと混同しやすい誤り。\nC：誤り。一部免除の場合、実際に納付した保険料に相当する部分は年金額の計算に算入される。免除された部分は国庫負担分相当が算入される。\nD：誤り。追納できる期間は免除・猶予を受けた月の翌月から起算して10年以内であるが、3年度を超えると加算額（利子相当）が上乗せされる。「利子なし」ではない。\n\n【頻出】学生納付特例は「受給資格期間○・年金額×（追納なし）」という点が最頻出。\n【混同注意】免除（国庫負担分は年金額に算入）と猶予・学生特例（年金額に算入されない）の違いが重要。"
