"explanation": "キャッシュフロー表における「可処分所得」は、年収（収入金額）から社会保険料・所得税・住民税等の非消費支出を差し引いた手取り収入のことをいい、実際の生活費等の支出の基準となる収入として各年に記載される。\n\nB：誤り。貯蓄残高は「前年末の貯蓄残高×（1＋運用利率）＋当年の年間収支」という式で計算する。運用利率を考慮することが正しい手順であり、「考慮しない」という記述は誤り。\nC：誤り。収入の変動率（例：給与上昇率1〜2%等）と支出の変動率（例：物価上昇率1%等）は項目ごとに異なる変動率を設定してよい。統一する必要はない。\nD：誤り。キャッシュフロー表はライフイベントの変化・収支の変化等に応じて定期的に見直し・更新することが重要。「一度作れば修正不要」は誤り。\n\n【頻出】貯蓄残高の計算式（前年残高×(1+運用利率)±年間収支）は計算問題でも頻出。\n【混同注意】可処分所得（手取り収入）と収入（総収入）の定義の違いは基本知識。"
