"explanation": "厚生年金保険の標準報酬月額の等級区分は、最低88,000円（第1級）から最高650,000円（第32級）の32等級ではなく、現行では第1級（88,000円）から第32級（650,000円）の32等級が設定されている。なお健康保険の標準報酬月額は50等級（1〜139万円）とより細かく区分されており、混同しやすい。\n\n実際には厚生年金の32等級という数字自体は正しいが、2024年度時点での正確な等級数・金額範囲として出題されている場合は最新情報の確認が必要。本問では選択肢Dの「32等級」という記述は正しい場合もあるが、試験では健康保険（50等級）と混同させる問題が多い。\n\nA：正しい。70歳未満が強制加入で、保険料は労使折半（厚生年金保険法第81条の2）。\nB：正しい。4分の3基準（労働時間・労働日数）を満たすパートは強制加入。\nC：正しい。産前産後・育児休業中は事業主申出により保険料免除（同法第81条の2第1項）。\n\n【頻出】厚生年金（32等級）と健康保険（50等級）の等級数の違いは混同問題として頻出。\n【混同注意】標準報酬月額の上限も厚生年金65万円・健康保険139万円と異なる点に注意。"
