"延長保険とは、保険料の払込みを中止して、その時点の解約返戻金を原資に保険金額を変えずに保険期間を延長する方法であり、保険種類は変わらない",
"払済保険に変更した場合、元の契約に付加していた特約（災害割増特約等）はそのまま継続される",
"延長保険に変更した場合、変更後の保険期間は元の契約の残存保険期間より長くなることが多い"
