"answer": 0,
"explanation": "払済保険とは、保険料払込みを中止し、その時点の解約返戻金を一時払い保険料として同種の保険（終身保険なら終身保険）に変更する方法。保険期間は変わらないが、保険金額は元の契約より小さくなる（保険会社の商品設計上の一般的な扱い）。\n\nB：誤り。延長保険は解約返戻金を原資に保険金額を変えずに保険期間を「定期保険として延長」する方法。保険種類が「定期保険」に変更される点が重要で、「保険種類は変わらない」という記述は誤り。\nC：誤り。払済保険・延長保険への変更時には、一般的に元の特約（災害割増特約・傷害特約等）は消滅する。リビングニーズ特約等は例外として継続できる場合もあるが、原則として特約は消滅。\nD：誤り。延長保険への変更後の保険期間は、解約返戻金の額によって定まるため、元の残存期間より短くなる場合が多い。\n\n【頻出】払済保険（保険期間そのまま・保険金額縮小）vs延長保険（保険金額そのまま・定期保険に変更）の対比は頻出。\n【混同注意】両変更とも「特約は原則消滅」「告知不要」という共通点も押さえること。"
