"explanation": "2012年1月以降締結の新契約における生命保険料控除は、①一般生命保険料控除、②介護医療保険料控除、③個人年金保険料控除の3区分に分かれ、所得税では各区分の控除限度額は最高4万円、3区分合計で最高12万円となる（所得税法第76条）。\n\nB：誤り。個人年金保険料控除の税制適格要件として、保険料払込期間は「10年以上」が必要だが、年金受取開始年齢は「60歳以上」、年金受取期間は「10年以上（または終身）」が正しい。なお本選択肢の内容は概ね正しいが、「年金受取開始年齢が60歳以上」の部分は正しく、Aが正解のためBは選ばれない。\nC：誤り。住民税の生命保険料控除限度額は所得税より低く、各区分最高2.8万円・合計最高7万円。\nD：誤り。団体信用生命保険（団信）の保険料は生命保険料控除の対象外。住宅ローンの金利に含まれて支払われる場合が多く、独立した控除対象にならない。\n\n【頻出】新契約の3区分・各4万円・合計12万円（所得税）はそのまま出題される頻出数値。\n【混同注意】住民税の控除額（各2.8万円・合計7万円）は所得税と異なる。旧契約（2011年以前）との比較問題も頻出。"
