"地震・噴火またはこれらによる津波を原因とする火災による損害は、火災保険では補償されず、地震保険に加入する必要がある",
"火災保険には「再調達価額（新価）」基準と「時価」基準があり、時価基準では損害時点での同等品の再取得に必要な金額が保険金として支払われる",
"住宅用の地震保険は火災保険に付帯する形で契約し、単独での加入はできない"
