"explanation": "時価基準とは、損害時点での保険の目的物の価値（再調達価額から経年劣化・使用消耗分を差し引いた額）を基準として保険金を計算する方式。「損害時点での同等品の再取得に必要な金額」は再調達価額（新価）基準の説明であり、時価基準の説明として誤り（保険業界の慣行・標準約款）。\n\nA：正しい。一部保険の場合、比例填補方式（損害額×保険金額÷保険価額）が適用されることがある。ただし実損払い特約等がある場合は異なる。\nB：正しい。地震・噴火・津波を原因とする損害は火災保険の免責事項であり、地震保険でのみ補償される。\nD：正しい。住宅用地震保険は火災保険への付帯が必須で、単独加入は不可（地震保険に関する法律第2条）。\n\n【頻出】地震・津波は火災保険の補償対象外（地震保険が必要）という点は最頻出のひっかけ。\n【混同注意】再調達価額（新価）基準と時価基準の違い：新価は現時点での同等品の価格、時価は新価から減価償却分を引いた金額。"
