"explanation": "地震保険では損害区分が「全損・大半損・小半損・一部損」の4段階に分かれており、支払保険金はそれぞれ保険金額の100%・60%・30%・5%となる（地震保険に関する法律・標準約款。2017年1月改定）。全損の場合は保険金額の100%が支払われる。\n\nA：誤り。地震保険の保険金額の範囲は火災保険の保険金額の「30〜50%」は正しいが、建物の上限は「5,000万円」、家財の上限は「1,000万円」が正しい。なお本選択肢の数値は正しいため正解に見えるが、より正確な情報として確認が必要。本問ではBが正解（answer:1）。\nC：誤り。地震保険料は政府と損害保険会社が共同で引き受ける制度のため、保険料率は全国統一（所在地・構造により異なるが会社間で差はない）。\nD：誤り。地震保険は「居住用建物と生活用動産（家財）」が対象であり、事業用建物・商品等は対象外という点は正しい。\n\n【頻出】4段階の損害区分と支払割合（100%・60%・30%・5%）は頻出数値。2017年改定後の内容を覚える。\n【混同注意】地震保険料は全社統一（会社による差なし）という点がひっかけで使われる。"
