"explanation": "医療保険には1入院あたりの支払限度日数（例：60日・120日型等）と、同一疾病の通算支払限度日数が設定されていることが多い。同一疾病で退院後に再入院した場合、退院から一定期間（例：180日）以内の再入院は同一入院として扱われ通算限度が適用される場合がある（各社の約款による）。\n\nB：誤り。がん保険の診断給付金は、商品によっては再発・転移・新たな原発がんの場合にも一定期間（例：2年）経過後に再支給される設計のものがある。「再発・転移では一切支払われない」とは言い切れない。\nC：誤り。急性心筋梗塞は「初めて発症し60日以上の労働制限」、脳卒中は「発症後60日以上の言語障害・運動障害等」といった追加要件が一般的に設定されている。がんのみが診断確定で即支払いとなることが多い。\nD：誤り。民間介護保険は公的介護保険の認定とは独立した独自の支払基準（ADL基準等）を持つ商品も存在する。\n\n【頻出】三大疾病の支払要件の違い（がん＝診断確定・心筋梗塞・脳卒中＝60日以上の状態継続）は頻出ひっかけ。\n【混同注意】1入院限度日数と通算限度日数の区別、および同一疾病の再入院の扱いは医療保険の重要論点。"
