"explanation": "総合福祉団体定期保険のヒューマン・ヴァリュー特約は、役員・従業員の死亡・高度障害に伴う企業の損失（代替要員の採用・育成コスト・業務損失等）を補償することを目的として企業が付加する特約で、保険金受取人は企業（法人）となる。\n\nA：誤り。総合福祉団体定期保険に加入するには、被保険者となる従業員の同意（被保険者同意）が必要（保険法第38条・同法第67条）。同意なしには加入できない。\nB：誤り。総合福祉団体定期保険の死亡保険金は、遺族（福祉給付金）部分は遺族が受取人となり、ヒューマン・ヴァリュー特約部分は会社が受取人となる二層構造の設計が一般的。\nD：誤り。総合福祉団体定期保険の保険料は会社（事業主）が全額負担し、損金算入が認められている。従業員が負担するのではない。\n\n【頻出】ヒューマン・ヴァリュー特約（企業の損失補償・受取人は法人）と福祉給付金（遺族補償・受取人は遺族）の二層構造は頻出。\n【混同注意】被保険者同意が必要な点（同意なし＝無効）と保険料負担者（会社）の区別を整理。"
