"answer": 2,
"explanation": "請負業者賠償責任保険は、建設・土木工事等の請負作業中に発生した事故による第三者への身体賠償・財物賠償責任を補償する保険。しかし「工事中の建物・設備（請負作業の目的物）の損害」は原則として補償対象外。工事目的物の損害は組立保険・建設工事保険等の別の保険が対応する領域。\n\nA：正しい。施設所有管理者賠償責任保険（施設賠）は施設の管理上の事故を補償。\nB：正しい。PL保険は製品の欠陥による賠償責任を補償するが、製品回収費用（リコール費用）は別途リコール保険等が対応する領域で、一般的なPL保険の対象外。\nD：正しい。使用者賠償責任保険は、労災保険では不足する部分（民事上の損害賠償請求への対応）を補完する保険。\n\n【頻出】各種賠償責任保険の補償対象（施設賠・PL保険・使用者賠償・個人賠償）の比較は頻出。\n【混同注意】請負業者賠責（第三者への賠償）と建設工事保険（工事目的物の物的損害）は別の保険。対象の違いを明確に区別する。"
