"explanation": "医療保険の入院給付金の支払形式は、「日帰り入院（1日）から支払う」タイプや「5日以上の入院から支払う（5日型・4日型等）」タイプなど複数の商品形態が存在する。「2種類のみが存在する」という記述は誤りであり、実際にはさまざまなタイプの商品がある（各社の商品設計による）。\n\nA：正しい。先進医療特約は厚生労働大臣が承認した先進医療の技術料を給付し、先進医療の種類は随時更新される。\nB：正しい。三大疾病特約等の保険金支払い後に契約が継続するタイプ（特約消滅・主契約継続）と、保険金支払いにより契約全体が消滅するタイプの両方が存在する。\nC：正しい。がん保険には加入直後の短期申告を防ぐため、90日（3ヵ月）の免責期間が設けられているのが一般的。\n\n【頻出】がん保険の90日免責期間は頻出。他の医療保険には免責期間がないことも対比で覚える。\n【混同注意】入院給付金の支払開始日（1日目・4日目等）は商品によって異なり、「一律」という断定的な記述は要注意。"
