"日銀短観（全国企業短期経済観測調査）は、内閣府が四半期ごとに実施する企業の景況感調査であり、業況判断DIが代表的な指標である",
"景気動向指数のコンポジット・インデックス（CI）において、一致指数が3ヵ月連続して同じ方向に動いた場合に景気の転換点と判断される"
