"answer": 1,
"explanation": "消費者物価指数（CPI）は、全国の一般世帯が購入する財・サービスの価格変動を総合的に測定する指標であり、総務省統計局が毎月公表している（統計法に基づく指定統計）。\n\nA：誤り。GDPは国内で生産された付加価値の合計であり、日本企業が「海外」で生産した分は含まれない。日本企業・外国企業を問わず「国内」で生産されたものが対象。日本国民が国内外で生産した分を集計するのはGNI（国民総所得）。\nC：誤り。日銀短観は「日本銀行」が四半期ごとに実施する調査。内閣府ではない。\nD：誤り。景気動向指数のDI（ディフュージョン・インデックス）において、一致指数が3ヵ月連続して50%を下回った月が景気の山・谷の目安とされる。CI（コンポジット・インデックス）は景気変動の大きさを測る指標で、「3ヵ月連続で同方向」はDIの景気転換点判断に近い説明だが正確ではない。\n\n【頻出】GDP（国内基準）とGNI（国民基準）の違い、日銀短観の実施主体（日本銀行）は頻出。\n【混同注意】CPI（総務省）とGDPデフレーター（内閣府）は異なる物価指標。実施主体の違いも整理する。"
