"explanation": "日経平均株価は225銘柄を「修正株価単純平均」で算出するため、株価の高い銘柄（値嵩株）の動きが指数全体に大きく影響する。TOPIXは時価総額加重方式で算出するため、時価総額の大きな銘柄（大型株）の影響が大きい。\n\nA：誤り。日経平均株価（日経225）はプライム市場の代表的な「225銘柄」の株価による単純平均方式。「全銘柄」「時価総額加重」はTOPIXの説明。\nB：誤り。TOPIXは東京証券取引所（旧東証一部、現プライム市場等）の「全銘柄」を時価総額加重で算出する指数。「225銘柄の単純平均」は日経平均の説明。\nD：誤り。NYダウは米国の代表的な30銘柄を株価平均（修正平均）で算出する指数。「500銘柄・時価総額加重・S&P500」はS&P500指数の説明。NYダウとS&P500は別の指数。\n\n【頻出】日経平均（225銘柄・単純平均→値嵩株に影響大）とTOPIX（全銘柄・時価総額加重→大型株に影響大）の比較は最頻出。\n【混同注意】NYダウ（30銘柄・株価平均）とS&P500（500銘柄・時価総額加重）は混同しやすい。別の指数として区別する。"
