"特定口座（源泉徴収あり）を利用した場合、証券会社が税金を計算・徴収するため、確定申告は一切不要であり、給付型の奨学金や扶養控除の所得判定にも影響しない",
"上場株式の売却損は、同一年内の上場株式の配当金と損益通算できるが、非上場株式の配当金とは損益通算できない"
