"explanation": "上場株式の譲渡所得（売却益）は申告分離課税の対象で、税率は所得税15%（復興特別所得税0.315%を含め15.315%）・住民税5%の合計20.315%が適用される（租税特別措置法第37条の11）。\n\nA：誤り。2024年以降の制度改正により、住民税については申告不要を選択した場合でも所得税の申告内容に連動する仕組みに統一された（申告方式の一致）。別途住民税の申告は原則として不要。\nC：誤り。特定口座（源泉徴収あり）でも、他の所得との損益通算等のために確定申告を選択することはできる。また源泉徴収された所得は「合計所得金額」や「総所得金額等」に算入される場合があり、奨学金や扶養控除の判定に影響する可能性がある。「一切不要・影響しない」という断定は誤り。\nD：正しい内容が含まれる。上場株式の売却損は上場株式等の配当所得と損益通算できる。非上場株式の配当金は申告分離課税の選択ができないため損益通算の対象外。\n\n【頻出】上場株式の税率（20.315%）と申告分離課税の仕組み、損益通算の範囲（上場株式同士のみ）は頻出。\n【混同注意】特定口座（源泉徴収あり）でも確定申告が「できる」（しなくてもよい）という点と、扶養控除等への影響の有無は注意が必要。"
