"explanation": "iDeCo（個人型確定拠出年金）の最大のメリットの一つは、運用期間中の利息・配当・売却益等の運用益が非課税であること（通常は20.315%の税金がかかるところ非課税）。これにより長期運用での複利効果が最大化される（確定拠出年金法第36条・所得税法）。\n\nA：誤り。iDeCoで運用できる商品は預貯金・保険・投資信託の3種類が基本。株式・債券への「直接投資」（個別銘柄の直接売買）は認められていないというのは正しいが、投資信託を通じた株式・債券への間接投資は可能。ただし「株式・債券への直接投資は認められていない」という記述自体は正しい。本問ではBが正解（answer:1）。\nC：誤り。iDeCoでは加入後も運用商品の配分変更（新規掛金の配分変更）やスイッチング（積立済み資産の移し替え）が可能。\nD：誤り。iDeCo内の損失は、iDeCo口座内の他の運用商品との通算はできるが、特定口座等の外部口座の利益との損益通算はできない。iDeCoは独立した税制適格制度のため。\n\n【頻出】iDeCoの3大税制優遇（掛金全額控除・運用益非課税・給付時の退職所得控除/公的年金等控除）はセットで頻出。\n【混同注意】iDeCo内の損益は外部口座と損益通算できない点は応用論点。NISAとの比較問題でも出題される。"
