"answer": 3,
"explanation": "先物取引は双方に履行義務があり、損失は理論上無限大になりうる（証拠金を超える損失が生じる場合、追加証拠金の差し入れが必要）。損失が「プレミアムの支払額に限定される」のはオプション取引の買い手のみの特徴。先物取引には損失限定の機能はなく、最大損失が限定されているという記述は誤り（デリバティブ取引の基本）。\n\nA：正しい。先物取引は売買双方に履行義務があり、権利のみを有するオプションとは異なる。\nB：正しい。金利スワップ（固定金利と変動金利の交換）・通貨スワップ（異なる通貨の元本・金利の交換）が代表的なスワップ取引。\nC：正しい。オプションの買い手は権利取得の対価としてプレミアムを支払い、売り手はプレミアムを受け取る代わりに買い手の権利行使に応じる義務を負う。\n\n【頻出】先物（双方義務・損失無限大の可能性）とオプション買い手（権利のみ・損失はプレミアムに限定）の非対称性は頻出。\n【混同注意】「損失限定＝オプション買い手のみ」という点。先物取引の損失は限定されない。"
