"explanation": "グロース（成長）投資は企業の将来の成長性・収益拡大に注目する投資スタイル。成長期待を折り込んでPERが高くなりやすく、業績が急成長している銘柄が対象となる。一方、成長期待が裏切られると株価が大きく下落するリスク（バリュエーション・リスク）がある。\n\nA：誤り。PERやPBRが低い割安銘柄への投資は「バリュー投資」の説明。グロース投資はPERが高い成長株への投資。\nB：誤り。将来の収益拡大に期待して高PERでも投資するのは「グロース投資」。バリュー投資は現在の指標（PER・PBR等）が低い割安銘柄への投資スタイル。\nD：誤り。バリュー投資はPER・PBR等の財務指標が低い（割安な）銘柄を選定するため、財務指標を積極的に活用する手法。「参考にしない」は誤り。\n\n【頻出】グロース投資（成長性重視・高PER）とバリュー投資（割安重視・低PER・低PBR）の対比は頻出。\n【混同注意】グロースとバリューの定義を逆に覚えないこと。「グロー＝成長」「バリュー＝価値（割安）」と語源から覚える。"
