"answer": 3,
"explanation": "カントリーリスクとは、投資先の国・地域における政治変動・経済混乱・外貨規制・戦争等によって投資収益が損なわれるリスク。新興国市場に特有のリスクとして論じられることが多いが、先進国間の投資であっても政治的不安定・政策変更等によりカントリーリスクが生じることがあり、「先進国間では発生しない」という断定は誤り。\n\nA：正しい。価格変動リスク（マーケット・リスク）は全ての市場性金融商品に存在する基本的なリスク。\nB：正しい。信用リスクはデフォルトリスクとも呼ばれ、格付け機関（S&P・Moody’s等）の格付けが低いほど高い信用リスクを示す。\nC：正しい。流動性リスクは取引量が少ない小型株・社債等で顕著に現れ、希望価格での売買ができないリスク。\n\n【頻出】4種類の主要リスク（価格変動・信用・流動性・カントリー）の定義は頻出。カントリーリスクが先進国にも存在する点は見落としやすい。\n【混同注意】流動性リスク（売買できない）と価格変動リスク（価格が下がる）は異なるリスク概念。"
