"explanation": "企業型DC・iDeCoでは、事業主または金融機関が選定・提示した運用商品ラインナップの中から加入者が選択する仕組みであり、個別の株式・債券等を自ら直接売買することはできない（確定拠出年金法第23条）。運用商品として提供されるのは投資信託・預貯金・保険等に限られる。\n\nA：誤り。運用指図を行わない（デフォルト状態の）場合に備えて「指定運用方法（デフォルト商品）」が設定されており、運用指図がなくても掛金は継続して拠出・運用される。\nC：誤り。確定拠出年金の制度内でのスイッチングによる売却益は非課税。DC口座内の運用益は給付時まで課税されない（運用期間中の非課税が最大のメリット）。\nD：誤り。転職の際には転職先の企業型DCへの移換、またはiDeCoへの移換（ポータビリティ制度）が認められている。自動的に脱退一時金として支払われるわけではない。\n\n【頻出】DC内のスイッチングでの売却益は非課税、転職時のポータビリティ（移換可能）は頻出ポイント。\n【混同注意】DC口座内の取引は非課税（課税は給付時のみ）という原則を、NISA・特定口座と混同しないこと。"
