"answer": 1,
"explanation": "所得税は原則として総合課税方式（各種所得を合算して超過累進税率を適用）を採用しているが、退職所得・山林所得・土地等の譲渡所得・株式の譲渡所得・利子所得等については申告分離課税または源泉分離課税が認められている（所得税法第22条・第89条）。\n\nA：誤り。所得税は個人に課税される税金。法人の所得には法人税が課税される。\nC：誤り。所得税は5%〜45%の7段階の超過累進税率が適用される。「一律20%の比例税率」は誤り。\nD：誤り。所得税の申告（確定申告）は原則として翌年2月16日から3月15日の間に行う年1回の申告。「毎月翌月末」は誤り。\n\n【頻出】総合課税（原則）と分離課税（例外）の区分、超過累進税率（5〜45%・7段階）は頻出基本知識。\n【混同注意】所得税（個人）と法人税（法人）は別の税金。申告期限（3月15日）と納付期限も整理する。"
