"explanation": "不動産所得とは土地・建物等の不動産の貸付けによる所得（賃料収入等）のこと。不動産の「売却（譲渡）」による所得は「譲渡所得」として区分される。不動産所得と譲渡所得は別の所得区分であり、「売却による所得も不動産所得に含まれる」という記述は誤り（所得税法第26条・第33条）。\n\nA：正しい。預貯金利子は源泉分離課税（20.315%）が原則。公社債の利子は申告分離課税（確定申告不要も可）。\nB：正しい。上場株式の配当金は総合課税・申告分離課税・申告不要の3方式から選択可能。\nD：正しい。事業所得＝総収入金額－必要経費（所得税法第27条）。青色申告特別控除等も適用可能。\n\n【頻出】不動産の「貸付け→不動産所得」「売却→譲渡所得」の区分は最頻出ひっかけ。\n【混同注意】10種類の所得区分（利子・配当・不動産・事業・給与・退職・山林・譲渡・一時・雑）は整理して記憶する。"
