"explanation": "給与所得の金額は「収入金額－給与所得控除額」で計算される（所得税法第28条）。給与所得控除は実際の経費を証明することなく収入に応じた一定額を控除できる概算控除（みなし経費）であり、給与所得者の経費に相当するものとして法律で定められている。\n\nB：誤り。給与所得控除額には上限が設けられており、2024年度では収入850万円超の場合の控除額は195万円が上限。収入増加に比例して無制限に増加するわけではない。\nC：誤り。給与収入が2,000万円以下でも、副業収入が20万円超・医療費控除を受けたい場合・2ヵ所以上から給与を受けている場合等は確定申告が必要。「すべて年末調整で完結」は誤り。\nD：誤り。特定支出控除は特定支出の合計額が給与所得控除額の2分の1を超える部分が控除される（超えた部分が全額ではなく、超えた部分を控除するという仕組みは正しいが、超えた全額が控除される点は正しい）。選択肢の記述は概ね正しいが、本問ではAが正解（answer:0）。\n\n【頻出】給与所得控除は概算控除（実費証明不要）・上限195万円（収入850万円超）は頻出数値。\n【混同注意】給与所得控除（概算）と特定支出控除（実額）は別制度。特定支出控除は控除額の1/2超の部分のみ適用。"
