"answer": 3,
"explanation": "配偶者控除の適用を受けるには、配偶者が「同一生計配偶者」の要件を満たす必要があり、その要件の一つが配偶者の合計所得金額が48万円以下（給与収入のみの場合は給与所得控除55万円を差し引くと収入103万円以下に相当）であること（所得税法第83条）。\n\nA：誤り。配偶者控除は配偶者の合計所得金額が48万円以下の場合に適用される。また控除額は納税者本人の合計所得金額に応じて異なり（900万円以下38万円・900〜950万円26万円・950〜1,000万円13万円）、一律38万円ではない。\nB：誤り。配偶者特別控除は配偶者の合計所得金額が48万円超133万円以下の場合に適用されるという点は正しい。しかし控除額は「配偶者の所得が高くなるほど逓減」かつ「納税者本人の所得が高くなるほど逓減」の両方が作用する（所得税法第83条の2）。\nC：誤り。配偶者控除と配偶者特別控除は同一年に重複して受けることはできない（いずれか一方のみ適用）。\n\n【頻出】配偶者控除の適用要件（配偶者所得48万円以下・本人所得1,000万円以下）と103万円の壁の関係は頻出。\n【混同注意】配偶者控除（所得48万円以下）と配偶者特別控除（48万円超〜133万円以下）の適用範囲の違いを整理。"
