"explanation": "住宅ローン控除の床面積要件は原則「50㎡以上」だが、合計所得金額が1,000万円以下の年については床面積「40㎡以上50㎡未満」の住宅でも適用可能（租税特別措置法第41条）。また所得上限は「2,000万円以下」だが、40〜50㎡の住宅は「1,000万円以下」という別の上限が設けられており、「2,000万円以下の年のみ」という記述は50㎡以上の住宅については正しいが、40〜50㎡の特例（1,000万円以下）を無視した不正確な記述となる。\n\nA：正しい。6ヵ月以内の入居要件と12月31日時点の居住継続要件は住宅ローン控除の基本要件（同法第41条第1項）。\nB：正しい。住民税からの控除（所得税で控除しきれない場合、住民税から最大136,500円を上限に控除）は正しい。\nC：正しい。初年度のみ確定申告が必要で、2年目以降は年末調整での適用が可能（給与所得者の場合）。\n\n【頻出】住宅ローン控除の所得上限（2,000万円以下）・床面積要件（50㎡以上、特例で40㎡以上）・初年度確定申告必要は頻出。\n【混同注意】40〜50㎡の特例（所得1,000万円以下）と通常（50㎡以上・2,000万円以下）の適用条件の違いを整理。"
