"explanation": "生活に通常必要でない資産（リゾートマンション・別荘・貴金属・競走馬等）の譲渡による損失は、他の所得との損益通算が認められていない（所得税法第69条第2項・同法施行令第200条）。生活に必要な資産（マイホーム等）の損失も一定の制限があり、「通常必要でない資産」の損失は完全に損益通算不可。\n\nA：正しい。不動産所得の損失は原則として損益通算可だが、土地購入借入金の利子部分に対応する損失は損益通算不可（租税特別措置法第41条の4）。\nB：正しい。事業所得の損失は、給与所得・配当所得・不動産所得等との損益通算が認められている（所得税法第69条）。\nC：正しい。上場株式等の譲渡損失は、申告分離課税を選択した上場株式等の配当所得とのみ損益通算可能。不動産所得・給与所得等とは損益通算不可（租税特別措置法第37条の12の2）。\n\n【頻出】損益通算の可否（不動産・事業・山林・譲渡損失は可、雑・一時・生活不必要資産の損失は不可）は最頻出。\n【混同注意】「生活に通常必要な資産」（家財等）の損失も損益通算不可（偶発的損失のため）という点も重要。"
