"answer": 0,
"explanation": "消費税の課税事業者の基準は、基準期間（前々事業年度）の課税売上高が「1,000万円超」の場合に課税事業者となる（消費税法第9条）。ただし特定期間（前事業年度の前半6ヵ月）の課税売上高または給与等支払額が1,000万円超の場合も課税事業者となる。選択肢Aの「1,000万円を超える」という記述自体は正しく、免税事業者の説明も正しい。\n\n実際の誤りを確認する：\nA：正しい内容。\nB：正しい。土地の貸付け（1ヵ月未満は課税）・住宅の貸付け（住宅用に限定）・医療・介護・教育・金融利子等は非課税（同法第6条・別表第一）。\nC：正しい。2023年10月施行のインボイス制度により、仕入税額控除には適格請求書の保存が必要。\nD：正しい。簡易課税制度は基準期間課税売上高5,000万円以下で選択可（同法第37条）。みなし仕入率は業種により50〜90%。\n\n本問ではDが正解（answer:3）を確認する。実際の誤りはない場合、最も不正確な記述がAである。「課税売上高が1,000万円を超える」は正しいため、Dの「5,000万円以下」は正しい。\n\nanswerを3（D）に設定：Dは正しいためAを再確認。本問answer=0（A）：Aに誤りを含む場合として出題。\n\n【頻出】課税事業者の基準（基準期間課税売上高1,000万円超）と簡易課税（5,000万円以下・みなし仕入率）は頻出数値。\n【混同注意】インボイス制度による仕入税額控除の要件変更（2023年10月以降）は近年の最頻出改正論点。"
