"explanation": "給与所得者が年末調整を受けていても、給与所得・退職所得以外の所得（副業収入等）の合計額が20万円を超える場合は確定申告が義務付けられる（所得税法第120条）。なお20万円以下であれば申告不要（住民税の申告は別途必要な場合あり）。\n\nA：誤り。自主的に期限後申告をした場合でも無申告加算税は課されるが、税務調査前に自主的に申告した場合は無申告加算税の税率が軽減される（5%に軽減等）。「免除」ではなく「軽減」が正確。\nC：誤り。確定申告書の提出期限と納税期限は原則として同じ3月15日。振替納税を利用した場合は4月下旬に引落しになるが、「3月31日まで猶予」という規定はない。\nD：誤り。e-Tax（国税電子申告・納税システム）を利用した電子申告は認められており、むしろ青色申告特別控除の65万円はe-Tax申告等が要件となっている。\n\n【頻出】「給与所得者の副業20万円超は確定申告必要」は最頻出論点。20万円以下は申告不要（ただし住民税は要申告の場合あり）。\n【混同注意】期限後申告の無申告加算税は「免除」ではなく「軽減」（自主申告の場合）。"
