"explanation": "役員報酬（役員給与）が法人税法上の損金に算入されるためには、①定期同額給与（毎月同額）、②事前確定届出給与（税務署への届出に基づく賞与等）、③業績連動給与（有価証券報告書提出法人等の要件あり）のいずれかに該当する必要がある（法人税法第34条）。これら以外の役員報酬は「不相当に高額な部分」や「不定期給与」として損金不算入となる。\n\nA：正しい税率だが、「令和7年度」の数値として「15%」と「23.2%」は一般的な数値。ただし令和7年度の改正を反映した確認が必要。本問ではDが正解（answer:3）。\nB：誤り。法人税法上の「益金」「損金」と企業会計上の「収益」「費用」は必ずしも一致しない（申告調整が必要な項目が存在する）。「完全に一致する」は誤り。\nC：誤り。交際費等は原則として損金不算入だが、中小法人（資本金1億円以下）は年800万円まで全額損金算入可、または接待飲食費の50%損金算入かのいずれかを選択できる（租税特別措置法第61条の4）。「すべて損金不算入」は誤り。\n\n【頻出】役員報酬の損金算入要件（定期同額・事前確定・業績連動の3種類）と交際費の損金算入限度（中小法人800万円）は頻出。\n【混同注意】役員報酬と使用人（従業員）給与は損金算入ルールが異なる。従業員給与は原則全額損金算入。"
