"不動産所得の損失は他の所得と損益通算できるが、土地取得のための借入金利子に相当する損失部分は損益通算の対象から除かれる",
"賃貸用建物の減価償却は定額法と定率法のどちらでも選択できるが、個人事業者が賃貸不動産を保有する場合は定率法が強制適用される",
