"障害者控除は、本人または生計を一にする配偶者・扶養親族が障害者である場合に適用され、一般の障害者は27万円、特別障害者は40万円の控除額となる",
"ひとり親控除は、婚姻歴の有無にかかわらず、生計を一にする子（総所得金額等48万円以下）を有する単身者（合計所得金額500万円以下）に35万円の控除が適用される",
"寄附金控除は、国・地方公共団体・特定公益増進法人等への寄附金のうち、2,000円を超える部分が所得から控除される"
