"answer": 1,
"explanation": "障害者控除の控除額は、一般の障害者が27万円（正しい）、特別障害者が40万円（誤り）。特別障害者の控除額は「75万円」が正しい（所得税法第79条）。なお特別障害者が同居している場合（同居特別障害者）は75万円となり、通常の特別障害者も75万円。「40万円」は誤りの数値。\n\nA：正しい。基礎控除の逓減・消失ルール（合計所得金額2,400万円超から段階的に減少・2,500万円超でゼロ）は2020年改正で導入（所得税法第86条）。\nC：正しい。ひとり親控除は2020年改正で創設。婚姻歴不問・所得500万円以下・子の所得48万円以下の要件を満たす場合に35万円控除（同法第81条の2）。\nD：正しい。寄附金控除は寄附金額（または総所得金額等の40%相当額のいずれか低い方）から2,000円を差し引いた金額が所得控除（同法第78条）。ふるさと納税も対象。\n\n【頻出】特別障害者控除額は75万円（40万円ではない）は数値問題として頻出のひっかけ。基礎控除の逓減も近年の改正ポイントとして頻出。\n【混同注意】障害者（27万円）・特別障害者（75万円）・同居特別障害者（75万円）の控除額を整理。"
