"answer": 0,
"explanation": "用途地域は市街化区域には少なくとも用途地域を定めることが義務付けられている（都市計画法第13条第1項）。市街化調整区域には原則として用途地域は定められない（例外的に定められる場合もある）。\n\nB：誤り。第一種低層住居専用地域でもコンビニエンスストアは建築不可だが、「診療所（病院は不可）」は建築可能。また小規模な店舗（床面積50㎡以内等）も一定条件で建築可能。「診療所も建築できない」という断定は誤り（建築基準法別表第二）。\nC：誤り。商業地域は商業・業務の利便性を図る地域だが、住宅・共同住宅の建築は認められている。商業地域に住宅が建てられないわけではない（建築基準法別表第二）。\nD：誤り。工業専用地域では住宅・店舗・学校・病院等の建築は原則として認められていない（工場・倉庫等のみが建築可能な最も規制の厳しい工業系用途地域）。\n\n【頻出】工業専用地域（住宅不可）・第一種低層住居専用地域（病院・大規模店舗不可）の建築制限は頻出。\n【混同注意】商業地域には住宅も建築可能という点は見落としやすい。用途地域ごとの建築可否は一覧で整理する。"
