"幅員4m未満の道路で特定行政庁が指定したものは2項道路（みなし道路）として扱われ、道路中心線から2m後退した線が道路境界線とみなされる",
"2項道路に接する土地に建物を建築する場合、道路中心線から2m後退した部分（セットバック部分）は建築物を建築できないが、建蔽率・容積率の計算上は敷地面積に算入される",
"私道であっても建築基準法の道路の要件を満たしていれば接道義務を充足できる"
