"explanation": "贈与税の配偶者控除（相続税法第21条の6）は、①婚姻期間20年以上の配偶者への贈与、②居住用不動産または居住用不動産取得のための金銭が贈与対象、③贈与税の課税価格から最高2,000万円を控除できる制度。\n\nB：誤り。同一の配偶者からの贈与については「一生に1回」しか適用できない（同条第2項）。「何度でも適用可」は誤り。\nC：誤り。贈与税の配偶者控除（2,000万円）＋基礎控除（110万円）＝最大2,110万円まで非課税となる点は正しいが、この控除を受けるためには「贈与税の申告書の提出」が必要（申告が要件）（同条第1項）。申告不要は誤り。\nD：正しい内容。国内の居住用不動産が対象であり、店舗兼住宅は居住用部分のみが対象となる。本問ではAが正解（answer:0）。\n\n【頻出】配偶者控除の要件（婚姻20年以上・居住用・最高2,000万円・一生1回・申告必要）はセットで頻出。\n【混同注意】相続税の配偶者税額軽減（婚姻期間不問）と贈与税の配偶者控除（婚姻20年以上）の適用要件の違いを整理。"
