"explanation": "直系尊属からの住宅取得等資金の贈与の非課税制度を利用できる受贈者の所得要件は、贈与を受けた年の合計所得金額が「2,000万円以下」（床面積40㎡以上50㎡未満の場合は1,000万円以下）（租税特別措置法第70条の2）。「3,000万円以下」は誤りの数値。\n\nA：正しい。省エネ等住宅（一定の省エネ性能・耐震性等を有する）は1,000万円、それ以外は500万円の非課税限度額（令和5年度の数値）。\nB：正しい。教育資金の一括贈与の非課税制度（租税特別措置法第70条の2の2）：1,500万円（学校等以外の塾等は500万円）。\nC：正しい。結婚・子育て資金の一括贈与の非課税制度（同法第70条の2の3）：1,000万円（結婚関係の費用は300万円）。\n\n【頻出】住宅取得等資金の非課税制度の所得要件（2,000万円以下）と3つの一括贈与非課税制度の限度額は頻出。\n【混同注意】3つの非課税特例（住宅取得・教育資金・結婚子育て）の非課税限度額と適用条件（所得要件等）を一覧で整理する。"
