"answer": 3,
"explanation": "貸宅地（借地権が設定された土地の地主からみた評価）の相続税評価額は「自用地評価額×（1－借地権割合）」で計算される（財産評価基本通達25）。借地権割合（地域によって30〜90%）が高いほど貸宅地の評価額は低くなる。\n\nA：誤り。上場株式の評価は①相続開始日の終値、②相続開始月の終値月平均額、③相続開始月の前月の終値月平均額、④相続開始月の前々月の終値月平均額の4つのうち「最も低い価格」で評価する（財産評価基本通達169）。「最も高い価格」は誤り。\nB：誤り。取引相場のない株式の評価方法の原則適用は、会社規模（大・中・小）によって異なる。「中会社」は類似業種比準方式と純資産価額方式の折衷方式（Lの割合を使った加重平均）が原則で正しいが、「小会社」は純資産価額方式が原則（同通達178〜189）。本選択肢の記述は中会社について概ね正しい。\nC：誤り。路線価地域の宅地評価は「路線価×面積」が基本だが、奥行距離補正率・不整形地補正率等の各種補正が適用される（同通達15等）。「補正は行わない」は誤り。\n\n【頻出】上場株式の評価（4つの価格のうち最低価格）と貸宅地評価（自用地×（1−借地権割合））は頻出。\n【混同注意】上場株式は「最も低い価格」（有利な評価）という点は「最も高い価格」と逆に覚えないよう注意。"
