"explanation": "75歳以上の者は後期高齢者医療制度の被保険者となるため（高齢者の医療の確保に関する法律第50条）、健康保険の被扶養者の資格を失う。75歳の誕生日に自動的に後期高齢者医療制度に移行し、子等の健康保険の被扶養者から外れることになる。\n\nA：誤り。被扶養者の認定要件は、同居の場合「年収が130万円未満（60歳以上・障害者は180万円未満）かつ被保険者の年収の2分の1未満」が条件。ただし被保険者の年収の2分の1以上でも、被保険者の年収を上回らなければ認定される場合もある（健康保険組合の判断による）。本選択肢の「2分の1未満」という絶対要件的な表現は一部の解釈では不正確。\nB：誤り。被扶養者として認定される同居親族の範囲はより広く、祖父母・配偶者の父母・曾祖父母等の直系尊属も同居であれば被扶養者になれる（健康保険法第3条第7項）。\nC：誤り。高額療養費制度は被扶養者（家族）にも適用される（家族療養費の高額療養費として処理）。\n\n【頻出】75歳になると後期高齢者医療制度に移行し、健康保険の被扶養者資格を喪失するという点は頻出。\n【混同注意】被扶養者の収入要件（130万円・180万円）と、同居・別居による認定範囲の違いを整理。"
