"explanation": "国民健康保険の保険料（税）は、①所得割（所得に応じた部分）、②均等割（被保険者1人あたり一定額）、③平等割（世帯あたり一定額）、④資産割（固定資産税額に応じた部分）の最大4要素で構成されるが、市区町村によって採用する要素数が異なり、すべての市区町村が4要素を採用しているわけではない（地方税法第703条の4）。\n\nA：誤り。会社退職後は自動的に国民健康保険に加入されるわけではなく、退職後14日以内に住所地の市区町村に届出・加入手続きが必要（国民健康保険法第9条）。健康保険の任意継続を選択することも可能。\nC：誤り。出産育児一時金は国民健康保険でも支給されるが、傷病手当金は国民健康保険では「任意給付」であり、全市区町村で支給されるわけではない（同法第58条）。\nD：誤り。国民健康保険料には所得割のほかに均等割・平等割等の定額部分があるため、低所得世帯に相対的に重い負担がかかる構造であり、「均等になるよう設計」という記述は誤り。\n\n【頻出】国民健康保険の傷病手当金は「任意給付（全市区町村で支給されない）」という点は頻出のひっかけ。\n【混同注意】健康保険（法定給付として傷病手当金あり）と国民健康保険（傷病手当金は任意給付）の違いを整理。"
