"explanation": "在職定時改定制度は2022年4月から導入され、65歳以上で在職中の老齢厚生年金受給者について、毎年10月1日に前年9月〜当年8月の被保険者期間分の年金額が改定される仕組み（厚生年金保険法第43条第2項）。従来は退職・70歳到達時のみ改定されていたが、在職中でも毎年反映されるようになった。\n\nB：正しい内容。在職老齢年金による支給停止は老齢厚生年金（報酬比例部分）が対象であり、老齢基礎年金は在職老齢年金の調整対象外で全額支給される（厚生年金保険法第46条）。本選択肢は正しいが本問ではAが正解（answer:0）。\nC：誤り。繰下げ待機中（繰下げを選択して受給を開始していない期間）は、在職老齢年金の支給停止の仕組みは直接適用されない（繰下げ待機中は年金を受給していないため）。\nD：誤り。70歳以降は厚生年金保険料の納付義務はないが（被保険者でなくなる）、厚生年金適用事業所に使用される場合は在職老齢年金の仕組みが適用される（厚生年金保険法第46条第6項）。\n\n【頻出】在職定時改定（2022年4月・毎年10月に改定）、在職老齢年金は老齢厚生年金のみ調整（老齢基礎年金は対象外）は頻出。\n【混同注意】65歳以上の在職老齢年金（支給停止基準月額50万円）と65歳未満の廃止された仕組みの違いも整理する。"
