"explanation": "確定給付企業年金（DB）には、①規約型（労使合意の年金規約に基づき事業主が信託銀行・生命保険会社等に資産を預けて運営）と②基金型（企業年金基金という法人格を持つ組織が給付を行う）の2種類がある（確定給付企業年金法第3条・第13条）。\n\nA：誤り。確定給付企業年金は将来の給付額が確定しており、運用リスクは事業主（会社）が負う。確定拠出年金（DC）では運用リスクを加入者が負う点と対比される。\nC：誤り。確定給付企業年金の給付は、年金（終身年金・有期年金等）として受け取ることが基本であり、一定の要件のもとで一時金での受取りも可能（同法第36条）。「一時金のみ」は誤り。\nD：誤り。確定給付企業年金においても、規約に定めることで加入者（従業員）が掛金の一部を拠出することができる（マッチング拠出に類似した仕組み）（同法第55条）。「事業主のみ」は誤り。\n\n【頻出】確定給付企業年金（DB）と確定拠出年金（DC）の運用リスク負担者（DBは事業主・DCは加入者）の違いは最頻出。\n【混同注意】規約型（事業主が直接）と基金型（基金が法人として独立）の違い、DBとDCの給付確定の仕組みの違いを整理。"
