"answer": 0,
"explanation": "介護保険の居宅サービスには要介護度ごとに支給限度基準額が定められており、この範囲内でサービスを利用した場合は所定の自己負担割合（1〜3割）を負担する。限度額を超えてサービスを利用した場合、超過分は保険給付されず「全額自己負担」となる（介護保険法第43条）。\n\nB：誤り。介護老人福祉施設（特養）は「要介護3以上」の者が利用対象（2015年の改正以降）。「要介護1以上」は誤り。また自己負担割合は所得に応じて1〜3割（一律1割ではない）。\nC：誤り。予防給付（要支援1・2向け）の支給限度基準額は要介護給付より「低く」設定されている（要支援1・2の限度額は要介護1〜5より低い）。\nD：誤り。居宅介護支援（ケアマネジャーによるケアプラン作成等）は、利用者の自己負担なし（全額保険給付）で利用できる（同法第46条）。「全額自己負担」は誤り。\n\n【頻出】特養の入所要件（要介護3以上）と、居宅介護支援（ケアマネジメント）は自己負担なしという点は頻出。\n【混同注意】限度額超過分は全額自己負担（保険給付なし）という仕組みと、限度額内の1〜3割自己負担の仕組みを混同しないこと。"
