"question": "老齢厚生年金の加給年金額に関する次のア〜エの記述のうち、正しいものの組み合わせはどれか。\n\nア：加給年金額は、老齢厚生年金の受給権者に厚生年金の被保険者期間が20年（240ヵ月）以上ある場合に加算要件が生じる\nイ：加給年金額の加算対象となる配偶者は、受給権者に生計を維持されている65歳未満の配偶者（年収850万円未満等）に限られる\nウ：配偶者への加給年金額は、配偶者が65歳になり老齢基礎年金を受給し始めた時点で支給が停止し、代わりに配偶者の老齢基礎年金に振替加算が加算される\nエ：加給年金額の加算対象となる子は、18歳到達年度末日までの子に限られ、障害状態にある子であっても20歳以上は対象外となる",
