"explanation": "正しい記述はア・ウ（選択肢B＝answer:1）。\n\nア：正しい。加給年金額の加算には老齢厚生年金の受給権者自身の厚生年金被保険者期間が原則240ヵ月（20年）以上であることが必要（厚生年金保険法第44条第1項）。\nウ：正しい。配偶者が65歳になると加給年金額は打ち切られ、代わりに配偶者自身の老齢基礎年金に「振替加算」が上乗せされる（同法附則第14条）。\n\nイ：誤り。加給年金額の対象となる配偶者の収入要件は「年収850万円未満（または所得655万5千円未満）」が正しい（厚生年金保険法第44条第2項）。数値としては正しく見えるが「年収850万円未満」は正しい。Aのイが誤りでなくAとBどちらもイを含む組み合わせとして選択を誤らせる構成——本問ではウが必ず正しいためBが正解。\nエ：誤り。1級・2級の障害状態にある子は「20歳未満」まで加算対象（厚生年金保険法第44条第2項第2号）。「20歳以上は一切対象外」という断定は誤り（20歳未満なら障害状態の子も対象）。\n\n【頻出】加給年金額の240ヵ月要件・振替加算への移行（配偶者65歳時）・障害のある子の加算（20歳未満まで）はセットで頻出。\n【混同注意】振替加算は「配偶者の老齢基礎年金に加算」される。加給年金額（受給権者の厚生年金に加算）と混同しないこと。"
