"answer": 0,
"explanation": "フラット35は住宅金融支援機構と民間金融機関が提携する全期間固定金利の住宅ローン。金利は「融資実行時（申込み時ではなく実際に融資が実行される時点）」の金利が適用されるのが原則だが、申込み時点の金利が適用されるとも言われる（金融機関・商品タイプによる）。全期間固定金利のため、借入期間中に市場金利が変動しても返済額は変わらない点が特徴（住宅金融支援機構法第35条）。\n\nB：誤り。フラット35の床面積要件は一戸建て住宅・マンション等ともに「70㎡以上」（一戸建て等）および「マンション等の共同住宅は30㎡以上」というのが正確（機構の審査基準）。「マンション50㎡以上」は誤り。\nC：誤り。フラット35の借入限度額は「8,000万円以内」かつ「建設費・購入価額以内」。年収に関係なく誰でも8,000万円まで借りられるわけではなく、年収に対する返済比率（年収400万円未満は30%以下・400万円以上は35%以下）の要件がある。\nD：誤り。フラット35と民間住宅ローンの併用（ペアローン等）は禁止されておらず、同一物件について組み合わせて利用することが認められている場合もある。\n\n【頻出】フラット35の全期間固定金利・床面積要件（一戸建て70㎡以上・共同住宅30㎡以上）・返済比率要件は頻出。\n【混同注意】フラット35の申込み時金利と融資実行時金利の関係は商品によって異なる。全期間固定という特徴が最重要。"
