"answer": 0,
"explanation": "合算対象期間（カラ期間）は、老齢基礎年金の受給資格期間（10年＝120ヵ月）を算定する際に算入できるが、年金額の計算（480ヵ月に対する実際の加入・免除期間）には算入されない期間（国民年金法附則第9条）。受給資格の判定だけに使われ、年金額には反映されない「空の期間」という意味。\n\nB：誤り。日本国籍を有する者が海外在住で任意加入の対象であったが加入しなかった期間（1961年4月〜1986年3月の国民年金強制加入前等）は「合算対象期間」に含まれ、受給資格期間の算定には算入される。「算入されない」は誤り。\nC：誤り。合算対象期間はあくまで受給資格期間の算定のみに使われる。年金額の計算には算入されないため、「年金額が増額される」という記述は誤り。\nD：誤り。1991年4月以前の学生期間（任意加入対象だったが加入しなかった期間）は「合算対象期間」として受給資格期間に算入される（国民年金法附則第5条第2項等）。「算入されない」は誤り。\n\n【頻出】合算対象期間（カラ期間）は「受給資格期間に算入○、年金額計算に算入×」という2点セットは最頻出。\n【混同注意】保険料免除期間（受給資格期間○・年金額に一部算入）とカラ期間（受給資格期間○・年金額に算入×）の違いを整理。"
