"explanation": "確定拠出年金の障害給付金は、加入者が障害状態になった場合に支給される給付であり、所得税法上「非課税所得」として扱われる（所得税法第9条・確定拠出年金法第36条第2項）。\n\nA：誤り。一時金受取は「退職所得」（退職所得控除適用）、年金受取は「雑所得（公的年金等控除適用）」として課税される。「給与所得」は誤り（バッチ1でも出題した論点だが別角度から出題）。\nB：誤り。DCの加入者が死亡した場合の死亡一時金は、相続税法上「みなし相続財産」として相続税の課税対象となる（相続税法第3条）。生命保険の死亡保険金と同様に500万円×法定相続人数の非課税枠が適用される。\nD：誤り。老齢給付金の受給開始可能年齢は通算加入者等期間によって異なり、10年以上あれば60歳から受給可能だが、期間が短い場合は受給開始年齢が繰り下がる（最長65歳から）（確定拠出年金法第33条）。「期間に関係なく60歳から」は誤り。\n\n【頻出】DC死亡一時金は相続税のみなし相続財産（非課税枠500万円×法定相続人数適用）と障害給付金の非課税扱いは頻出。\n【混同注意】DC老齢給付金の受給開始年齢（通算加入期間10年以上→60歳・短い場合は繰下がり）の仕組みを整理。"
