"explanation": "税理士資格のないFPが個別具体的な税務相談・税務書類の作成代行を行うことは税理士法第52条（非税理士による税理士業務の禁止）に違反する。ただし仮定の事例による一般的な説明・パンフレット等を用いた一般的な説明は「税理士業務」に該当せず、合法的に行うことができる。\n\nB：誤り。社会保険労務士（社労士）資格がないFPが、労務管理の具体的なアドバイスや帳票類の作成代行（社労士の業務範囲）を行うことは社会保険労務士法に違反する。\nC：誤り。遺言書の文案全体を作成することは、法律事務の一種として弁護士法第72条の「法律事務」に該当する可能性があり、弁護士資格のない者が報酬を得て行うことは問題がある。一般的な遺言の説明はできるが、個別文案の全体作成は注意が必要。\nD：誤り。保険証券の内容分析・保障の過不足の指摘は保険募集（勧誘・申込受付）ではなく「コンサルティング行為」であり、保険業法上の保険募集人の資格がなくても行うことができる（保険業法第2条第26項の「募集」には該当しない）。\n\n【頻出】FPの業際問題（税理士・社労士・弁護士・保険募集人等の資格が必要な業務の範囲）は頻出。「一般的説明→合法・個別具体的行為→資格必要」という線引きを覚える。\n【混同注意】保険証券の分析（合法・資格不要）と保険募集・勧誘行為（保険募集人資格必要）の違いを区別する。"
