"explanation": "個人情報保護法における「個人情報」は「生存する個人に関する情報」と定義されており（個人情報保護法第2条第1項）、死亡した者に関する情報は同法の直接の保護対象とはならない（ただし遺族等の生存者の情報と結びついている場合は別途検討が必要）。\n\nB：誤り。利用目的の変更は、変更前の目的と「関連性が合理的に認められる範囲内」であれば可能（同法第17条）。「一切認められていない」は誤り。\nC：誤り。第三者提供が許容される例外として、①法令に基づく場合、②人の生命・身体・財産の保護に必要な場合、③公衆衛生・児童の健全育成に特に必要な場合、④国の機関等への協力等がある（同法第27条第1項各号）。「例外なく違反する」は誤り。\nD：誤り。開示・訂正・削除等の請求に対して、事業者は一定の例外事由（業務の適正な実施に著しい支障を及ぼす場合等）がある場合は、請求の全部または一部を拒否することができる（同法第33条・第34条）。\n\n【頻出】個人情報の定義（生存する個人に関する情報）、第三者提供の例外規定（法令に基づく場合等）は頻出。\n【混同注意】個人情報（単体で個人識別可能）・個人データ（データベース化されたもの）・保有個人データ（開示等請求の対象）の3段階の概念を整理。"
