"explanation": "中小企業退職金共済（中退共）は、事業主が掛金を拠出して積み立て、従業員の退職時に中退共機構から直接従業員に退職金が支払われる仕組み（中小企業退職金共済法第2条等）。事業主は退職金の財源を自社で管理する必要がなく、外部積立によって確実に退職金を準備できる点がメリット。\n\nA：誤り。小規模企業共済の掛金払込期間が「1年未満（12ヵ月未満）」の場合は共済金Aが支給されない等の制限があるが、「6ヵ月未満」ではなく正確には掛金納付月数によって受取額・受取可否が変わる（小規模企業共済法等）。\nB：正しい内容。掛金は月額1,000円〜70,000円・500円単位・前納割引あり。本問ではCが正解（answer:2）。\nD：誤り。特定退職金共済（特退共）は商工会議所等が運営するが、掛金は「事業主が全額負担」する。従業員に掛金負担を求める制度ではない。\n\n【頻出】中退共の退職金は「中退共から直接従業員へ支払い（事業主を介さない）」という点は頻出。\n【混同注意】中退共（全国的な公的制度）と特退共（地域の商工会議所等が運営）の違い、どちらも事業主が掛金全額負担という共通点を整理。"
