"explanation": "65歳以降の遺族厚生年金と老齢厚生年金の併給については、原則として「老齢厚生年金は全額支給」され、「遺族厚生年金は遺族厚生年金の額から老齢厚生年金の額を差し引いた差額分のみ支給」される（厚生年金保険法第64条の2）。双方の「全額」を受給することはできない。\n\nA：正しい。2014年の法改正以降、遺族基礎年金の受給対象は「子のある配偶者」または「子」に限定され、子のない配偶者は対象外（国民年金法第37条）。\nB：正しい。遺族基礎年金の「子」の年齢要件（18歳年度末・障害1・2級は20歳未満）は正しい（同法第37条の2）。\nC：正しい。中高齢寡婦加算は40歳以上65歳未満の子のない妻（または子が年齢要件を超えて遺族基礎年金を失った妻）に加算される遺族厚生年金の加算制度（厚生年金保険法第62条）。\n\n【頻出】65歳以降の遺族厚生年金と老齢厚生年金の併給調整（差額支給）は頻出の応用論点。「全額併給不可」が重要。\n【混同注意】老齢基礎年金は遺族厚生年金と全額併給可能だが、老齢厚生年金は遺族厚生年金と差額のみ支給という点を整理。"
