"explanation": "キャッシュフロー表の「可処分所得」は、年間収入（給与収入等）から社会保険料・所得税・住民税等の非消費支出を差し引いた手取り収入のこと。家計の実際の支出・貯蓄の原資となる金額であり、手取り収入とほぼ同義として使われる。\n\nB：誤り。貯蓄残高の計算式は「前年末の貯蓄残高×（1＋運用利率）±当年の年間収支」が正しく、運用益（運用利率）を考慮する。「運用益を考慮しない」は誤り（ライフプランニングの基本計算）。\nC：誤り。キャッシュフロー表の改善策には収入増加（昇給・副業・配偶者就労等）も有効であり、支出削減のみが手段ではない。収入・支出・運用利率の各面からの改善を検討するのがFP業務の基本。\nD：誤り。将来の支出予測では、費目ごとに異なる変動率（物価変動率・教育費上昇率・医療費増加率等）を設定することが現実的であり、「一律の変動率が義務付けられている」という法的規定は存在しない。\n\n【頻出】可処分所得（収入−非消費支出）と貯蓄残高の計算式（前年残高×（1＋運用利率）±収支）は毎回確認すべき基本事項。\n【混同注意】収入金額（税込み）と可処分所得（手取り）の違い、および貯蓄残高の計算で運用利率を「乗じる」ことを忘れないこと。"
