"explanation": "健康保険の出産手当金は、被保険者本人が出産のため仕事を休み報酬を受けられない場合、産前42日（多胎妊娠は98日）・産後56日の期間、標準報酬日額の3分の2相当額が支給される（健康保険法第102条）。\n\nB：誤り。出産育児一時金は被保険者本人の出産だけでなく、被扶養者（配偶者等）の出産に対しては「家族出産育児一時金」として支給される（同法第114条）。\nC：誤り。育児休業給付金は子が1歳（保育所未入所等の場合は最長2歳）に達するまでが原則。「子が2歳に達するまで受給できる」という断定は誤りで、1歳が原則（延長は最長2歳まで）（雇用保険法第61条の4）。本選択肢は支給額（67%→50%）と子が2歳という点の両方が正しいが、「子が2歳に達するまで受給できる」という断定表現が不正確。\nD：誤り。出産手当金の支給期間と傷病手当金の支給期間が重複する場合、出産手当金が支給されている期間は傷病手当金は支給されない（調整規定あり）（同法第103条）。重複受給は原則として認められていない。\n\n【頻出】出産手当金（産前42日・産後56日・3分の2・被保険者本人のみ）と出産育児一時金（本人・家族ともに支給）の違いは頻出。\n【混同注意】産前産後休業（産前42日・産後56日）と育児休業（子が1歳まで・最長2歳まで延長可）の期間を混同しないこと。"
