"explanation": "特定理由離職者のうち、有期労働契約の期間満了に際して更新を希望したが更新されなかったことによる離職は、特定受給資格者に準じた取扱い（所定給付日数の優遇等）を受けることができる場合がある（雇用保険法第23条第2項）。\n\nA：誤り。自己都合退職は原則として一般受給資格者となり、特定理由離職者には「正当な理由のある自己都合退職」（病気・家族の介護・育児等）が該当する。すべての自己都合退職が特定理由離職者ではない。\nB：正しい内容。特定受給資格者の受給資格要件は「離職前1年間に6ヵ月以上」で正しい。本問ではCが正解（answer:2）。\nD：誤り。特定受給資格者・特定理由離職者（正当な理由のある離職）は、基本手当の給付制限（2〜3ヵ月）が適用されない。自己都合退職者に給付制限が適用される（雇用保険法第21条）。\n\n【頻出】特定受給資格者（会社都合・倒産等）と一般受給資格者（自己都合等）の給付制限・給付日数・受給要件の違いは頻出。\n【混同注意】給付制限（2〜3ヵ月）は自己都合退職者に適用（特定受給資格者・特定理由離職者は不適用）という点は基本知識として重要。"
