"answer": 3,
"explanation": "転換社債型新株予約権付社債（CB）は転換権を行使するまで社債として機能するため、株価が下落して転換が不利な場合でも、転換しない限り社債として引き続き利子を受け取ることができる。「株価が下落した場合は利子を受け取り続けることはできない」という記述は誤り（転換しない選択をすれば利子は継続）（社債・株式等の振替に関する法律の基本的な仕組み）。\n\nA：正しい。物価連動国債は元本がCPIに連動して増減し、インフレ時の実質購買力の維持に役立つ。\nB：正しい。変動利付国債は市場金利に連動して利率が変動するため、金利上昇局面では固定利付債より相対的に有利となる。\nC：正しい。劣後債は弁済順位が低い（シニア債より後）リスクの代わりに高利率。ただし株式よりは優先される（株式が最後）。\n\n【頻出】CBの「転換しない選択肢がある（下落時も利子継続）」という特性は頻出。「ダウンサイド保護あり・アップサイド参加あり」がCBの魅力。\n【混同注意】劣後債の弁済順位（普通社債の後・株式の前）という3段階の順序を整理する。"
