"explanation": "ファンド・オブ・ファンズは複数の投資信託（子ファンド）に投資する親ファンドの仕組みで、広範な分散投資が可能となる一方、親ファンドと子ファンドの双方で信託報酬等のコストが発生する（二重コスト）デメリットがある（投資信託及び投資法人に関する法律）。\n\nA：誤り。J-REIT（不動産投資信託）は「会社型」（投資法人という法人格を持つ組織）の一種であり、「契約型」ではない（投資信託及び投資法人に関する法律第2条）。\nB：正しい内容。公社債投資信託は株式を組み入れないが、元本保証はない点は正しい。本問ではDが正解（answer:3）。\nC：誤り。毎月分配型は分配金を毎月支払うが、収益の範囲を超えた「特別分配金（元本払戻金）」が発生する場合、元本を取り崩して分配することになり、長期の資産形成には必ずしも最適ではない。\n\n【頻出】J-REITは「会社型」（契約型ではない）、ファンド・オブ・ファンズの二重コスト問題は頻出。\n【混同注意】毎月分配型の「普通分配金（課税）」と「特別分配金（元本払戻・非課税）」の区別も重要な関連知識。"
