"explanation": "通貨オプションのプット・オプション（外貨を一定レートで売る権利）は、円高になった場合（外貨安・円高）に権利を行使することで損失を限定できるヘッジ手段。外貨建て資産を保有する投資家が円高リスクをヘッジする際に活用できる（デリバティブの応用）。\n\nA：誤り。為替予約で固定したレートより実際に円安になった場合、予約した（固定した）レートより円高に近いレートで決済することになるが、これは「損失」というよりも「利益機会を失った」状況。一方、円高になった場合は予約しておいた方が有利（円高リスクを回避）。選択肢の「予約時点より円安になった場合は損失」という方向性は事実上正しいが文脈として不正確。\nC：誤り。為替スワップは直物と先物を組み合わせた取引で、金利差（スワップポイント）が取引価格に反映される。「金利差の交換を主目的とした取引ではない」という記述は誤りで、スワップポイント（金利差）が為替スワップの重要な要素。\nD：誤り。外貨建て債券の利子を円換算する際には受取時点の為替レートが適用されるため、円換算後の受取額は為替レートの変動によって変化する。「一定となる」は誤り。\n\n【頻出】プット・オプション（外貨を売る権利→円高ヘッジ）とコール・オプション（外貨を買う権利→円安への対応）の使い分けは頻出。\n【混同注意】為替予約（権利・義務→双方に履行義務）とオプション（買い手に権利のみ→義務なし）の違いを整理。"
