"explanation": "信用格付けは民間の格付け機関（ムーディーズ・S&P・フィッチ等）が発行体の債務履行能力を評価して付与するものであり、あくまでも信用力の評価・意見に過ぎず、将来の債券価格変動や元本の返済を保証するものではない（格付けの本質的な性格）。\n\nA：正しい内容。BBB格（S&P・フィッチ）またはBaa格（ムーディーズ）以上が投資適格格付け。BB格（S&P）・Ba格（ムーディーズ）以下が投機的格付け（ハイイールド債・ジャンク債）。本問ではDが正解（answer:3）。\nB：誤り。信用スプレッドは信用力が「低い」（格付けが低い）発行体ほど投資家がより高いリターンを要求するため拡大する。「信用力が高いほどスプレッドが拡大」は逆の関係。\nC：誤り。格付けが高い（信用力高い）债券は安全性が高い代わりに利回りが「低く」、格付けが低い（信用力低い）債券はリスクの代償として利回りが「高い」。逆の記述。\n\n【頻出】投資適格格付け（BBB以上）とハイイールド債（BB以下）の区分、信用力と利回りの逆相関（信用力高→利回り低・スプレッド小）は頻出。\n【混同注意】格付けが高い→利回り低・スプレッド小、格付けが低い→利回り高・スプレッド大、という関係を整理する。"
