"explanation": "異なる資産クラス（国内株式・海外株式・債券・不動産等）に分散投資することで、各資産の値動きの相関が低い場合（一方が下落しても他方が上昇・横ばい等）にリスクの相殺効果が生まれ、ポートフォリオ全体のリスクを低減できる（現代ポートフォリオ理論）。\n\nA：誤り。同一資産クラス内の銘柄分散では非システマティック・リスク（個別銘柄リスク）を低減できるが、システマティック・リスク（市場全体のリスク）は分散投資では除去できない。「完全に除去」は誤り。\nC：誤り。相関係数が「低い（またはマイナス）」資産を組み合わせるほどリスク低減効果が大きい。「相関係数が高い」ほど効果が大きいは逆の関係（相関係数＋1では効果がない）。\nD：誤り。長期投資・分散投資によってリスクを低減することはできるが、投資元本の損失リスクを「完全にゼロ」にすることはできない（元本保証は預金保険制度対象の預金等に限る）。\n\n【頻出】分散投資で除去できるリスク（非システマティック・個別リスク）と除去できないリスク（システマティック・市場リスク）の区別は最頻出。\n【混同注意】相関係数と分散効果の関係（低相関・逆相関ほど効果大、高相関ほど効果小）を正確に覚える。"
