"explanation": "金融サービス提供法（旧金融商品販売法、2021年改正）は、金融商品の販売・勧誘において①重要事項の説明義務、②断定的判断の提供禁止（「必ず値上がりする」等の断言禁止）等を規定し、違反した場合に販売業者が顧客に生じた損害を賠償する責任を負うことを定めている（金融サービスの提供及び利用環境の整備等に関する法律第4条等）。\n\nB：誤り。消費者契約法は消費者と事業者の契約全般に適用され、金融商品（保険・投資信託等）の契約にも適用される（消費者契約法第2条）。金融商品を除外する規定はない。\nC：誤り。特定投資家（プロ投資家）は、申請することで一般投資家として取り扱うよう求めること（「一般顧客への移行」）が認められている場合もある（金融商品取引法第34条の2・第34条の4）。双方向の移行が一定の条件のもとで可能。\nD：誤り。犯罪収益移転防止法に基づく取引時確認は、新規口座開設時だけでなく、高額取引・一定の場合の既存顧客との取引等にも義務付けられている（犯罪収益移転防止法第4条）。「新規口座のみ」は誤り。\n\n【頻出】金融サービス提供法の重要事項説明義務・断定的判断提供禁止と損害賠償責任の関係は頻出。\n【混同注意】金融商品取引法（有価証券・デリバティブが主対象）と金融サービス提供法（より広い金融商品の販売行為を規制）の適用範囲の違いを整理。"
