"explanation": "株主割当増資は、既存株主の持株比率に応じて新株引受権を付与する増資方法。すべての既存株主が同率で権利を行使すれば、各株主の持株比率は変化しない（希薄化しない）という特徴がある（会社法第202条）。これは第三者割当増資（特定の者に新株を割り当て→既存株主の比率が希薄化）と対比される。\n\nA：誤り。発行市場（プライマリーマーケット）は「新規に発行される株式・債券等を投資家が購入する市場」（発行体から投資家への資金調達の場）。「既発行の株式が投資家間で売買される」のは流通市場（セカンダリーマーケット）の説明。\nB：誤り。IPOの公開価格はブックビルディング方式（投資家の需要を調査して価格を決定）等によって決定され、市場の需要動向が反映される。発行会社が一方的に固定するわけではない。\nC：誤り。流通市場での取引は「既存の株式が投資家間で売買される」ものであり、この取引の資金は発行体企業には流入しない（投資家間の資金移動）。発行体に資金が流入するのは発行市場（増資等）の場合。\n\n【頻出】発行市場（新規発行・発行体に資金流入）と流通市場（既発行株の売買・発行体に資金流入なし）の区別は頻出。\n【混同注意】株主割当増資（持株比率希薄化なし）と第三者割当増資（既存株主の比率希薄化あり）・公募増資の違いを整理。"
