"explanation": "株価指数先物を「売る」（ショートポジション）と、株価指数が下落した場合に利益が発生する。株式現物を大量に保有する投資家が先物を売ることで、保有株式の下落損失を先物の利益で相殺するヘッジ戦略（ヘッジング）として活用できる（デリバティブの基本的な活用方法）。\n\nB：誤り。変動金利受取・固定金利支払の金利スワップでは、市場金利が「上昇」すると受け取る変動金利が増加するため、このポジションは金利上昇時に「有利」（利益）となる。「損失を被る」は誤り。\nC：誤り。プット・オプションの売り手は、原資産価格が大幅に下落した場合に大きな損失が生じる可能性がある（理論上の損失は行使価格まで無限大に近い大きさ）。「限定された損失しか生じない」のはオプションの「買い手」の特性。\nD：誤り。先物取引では差金決済（反対売買による決済）が一般的だが、現物の受渡しによる決済も認められている取引がある（農産物・エネルギー先物等の商品先物では現物受渡しが基本）。「必ず差金決済」という断定は誤り。\n\n【頻出】先物の売り（下落時利益・ヘッジに活用）と買い（上昇時利益）の基本、金利スワップの損得方向（変動受取→金利上昇で有利）は頻出。\n【混同注意】オプションの買い手（損失限定・利益無限大）と売り手（利益限定・損失無限大）の非対称性を逆に覚えないこと。"
