"explanation": "普通分配金は、分配金落ち後の基準価額が投資家の個別元本（取得価格）を上回っている場合に支払われる分配金で、運用による収益部分からの分配として課税対象（配当所得として20.315%の税率）となる（所得税法・投資信託の税務）。\n\nA：誤り。分配金は運用益だけでなく、投資元本の一部を取り崩して支払われる「特別分配金（元本払戻金）」の形で支払われる場合もある。この場合は投資元本が減少する。\nC：誤り。特別分配金（元本払戻金）は投資家が投資した元本の一部が戻ってくるものとして扱われ、「非課税」である（課税対象とならない）。「課税対象となる」は誤り。\nD：誤り。毎月分配型投資信託は分配金を毎月支払うが、基準価額の下落を伴わない保証はなく、特別分配金（元本払戻）が発生することもある。「分配金が保証」「最も適した」という断定は誤り。\n\n【頻出】普通分配金（課税・収益から）と特別分配金・元本払戻金（非課税・元本から）の区別は最頻出。\n【混同注意】特別分配金の「非課税」という性質は「元本が戻ってくるだけで利益ではない」から非課税、という本質を理解する。"
