"explanation": "資金決済法（第2条・第63条の2以下）により、暗号資産交換業（暗号資産の売買・交換・管理等）を営む者は金融庁または財務局への登録が必要。無登録での暗号資産交換業は禁止されており、違反した場合は刑事罰の対象となる。\n\nB：誤り。暗号資産による利益（売却益・交換益・採掘報酬等）は「雑所得」として総合課税の対象であり、他の所得と合算して確定申告が必要（所得税法第35条）。非課税所得ではない。\nC：誤り。暗号資産は預金保険制度の保護対象外。暗号資産交換業者が破綻した場合、顧客の暗号資産は分別管理義務（資金決済法第63条の11）により保護されているが、全額保護が保証されているわけではない。\nD：誤り。ブロックチェーン技術による取引記録は公開されており（パブリックチェーンの場合）、KYC（顧客確認）義務のある取引所経由の取引は税務当局が把握可能。完全匿名・把握不可能という記述は誤り。\n\n【頻出】暗号資産の利益は雑所得（総合課税・最高税率55%）として課税対象、暗号資産交換業者の登録義務（資金決済法）は頻出。\n【混同注意】暗号資産（雑所得・総合課税）とNISA・iDeCo（非課税・優遇あり）の税務上の扱いの大きな差に注意。"
