"explanation": "インパクト投資（Impact Investing）は、財務的リターンの追求に加えて、社会的・環境的に「測定可能なポジティブな変化（インパクト）」を意図的に生み出すことを目的とした投資手法。ESG投資の一形態として位置づけられ、投資の社会的効果を定量的に測定・評価することに重点を置く。\n\nA：誤り。ESG投資はEnvironment（環境）・Social（社会）・Governance（ガバナンス）の非財務情報を財務情報とともに考慮する投資手法（定義そのものの否定）。\nB：誤り。ESG評価が高い企業への投資が必ずリターンが高いことは証明されておらず、リターンに関しては研究によって結果が異なる。「唯一の手法」「必ず高い」という断定も誤り。\nD：誤り。グリーンウォッシングとは、実際にはESGへの取り組みが不十分な企業や商品が、環境・社会への配慮を「過大に宣伝・見せかける行為」のことをいう（定義が逆の記述）。\n\n【頻出】ESG投資の定義（E・S・G三要素）とグリーンウォッシング（見せかけのESG）の区別、インパクト投資（測定可能な社会的影響）は近年頻出論点。\n【混同注意】グリーンウォッシング（過大宣伝・見せかけ）の定義を逆に理解しないこと。"
