"為替ヘッジを行うことで為替変動リスクをゼロにすることができ、コストもかからないため、常に為替ヘッジを行うことが合理的な選択である",
"外国株式ファンドの為替ヘッジあり（ヘッジコスト考慮）とヘッジなしを比較した場合、円高局面ではヘッジありの方が相対的に有利となる",
"新興国（エマージング）株式への投資は、先進国株式より一般的に高いリターンが期待できるが、政治・経済の安定性が高く為替リスクが低いため、リスクも先進国株式と同程度である"
