"answer": 3,
"explanation": "投資信託の解約・売却による利益（譲渡益）は、株式型・公社債型を問わず「譲渡所得（申告分離課税・税率20.315%）」として課税される（租税特別措置法第37条の10等）。「公社債投資信託の場合は利子所得」という記述は誤りで、公社債投資信託の解約・売却益も譲渡所得として申告分離課税の対象。なお公社債投資信託の「分配金」は利子所得として扱われる。\n\nA：正しい。上場株式の配当金を総合課税で申告した場合、配当控除（課税総所得金額1,000万円以下の部分は10%・超の部分は5%）を活用できる（所得税法第92条）。\nB：正しい。特定口座（源泉徴収あり）は申告不要を選択できるが、損益通算・繰越控除を行う場合は確定申告が必要。\nC：正しい。上場株式等の譲渡損失の繰越控除は3年間繰り越し可能だが、損失年・繰越控除年ともに確定申告が必要（租税特別措置法第37条の12の2）。\n\n【頻出】投資信託の解約・売却益は「譲渡所得（申告分離課税）」であり、分配金の種類（普通分配→配当所得・特別分配→非課税）と区別することは頻出。\n【混同注意】公社債投資信託の「分配金（利子所得）」と「解約・売却益（譲渡所得）」の課税区分の違いを整理。"
