"answer": 1,
"explanation": "J-REITは主に不動産の賃料収入を分配するが、借入金（デット）によるレバレッジを活用している場合が多いため、市場金利が上昇すると①借入コスト増加→分配金原資の減少、②将来の分配金の現在価値（割引率上昇→価値低下）等の要因から価格下落圧力がかかる傾向がある（不動産投資の基本的なリスク）。\n\nA：誤り。J-REITの分配金は賃料収入に基づくが、景気後退時には空室率上昇・賃料下落・テナントの退去等が生じる可能性があり、「景気動向の影響を受けない」という断定は誤り。\nC：誤り。J-REITは証券取引所に上場されており、一般的に数万円〜数十万円程度（1口あたり）から購入可能。「数億円以上」は誤り（実物不動産は数億円以上が一般的だが、J-REITは小口化されている）。\nD：誤り。J-REITは証券取引所に上場されており、市場が開いている時間であればリアルタイムで売買できる高い流動性がある。実物不動産と比較した流動性の高さがJ-REITの特徴の一つ。\n\n【頻出】J-REITの金利上昇時の価格下落傾向（借入コスト増・割引率上昇）と、実物不動産との比較（小口・流動性高・税負担なし）は頻出。\n【混同注意】J-REIT（証券・高流動性・小口）と実物不動産（高額・低流動性・管理負担あり）の違いを対比で整理。"
