"answer": 2,
"explanation": "過去の運用実績が将来の運用成績を「保証する」ことはない（目論見書等に「過去の運用実績は将来の運用成果を保証するものではありません」と明記されている）。ファンド選択においては信託報酬・投資哲学・運用チームの安定性・ベンチマーク等も考慮する必要があり、「過去実績が最優先で将来が保証される」という記述は誤り（金融商品取引法上も断定的判断の提供は禁止）。\n\nA：正しい。近い将来使用する資金は元本変動リスクが低い流動性の高い商品で管理することがFPの基本的な考え方。\nB：正しい。長期の積立投資においては、時間分散効果・複利効果を活かすために株式等を含む分散投資が有効な選択肢となる。\nD：正しい。ライフサイクルに応じたリスク許容度の変化に合わせた資産配分の見直し（リバランス・資産シフト）はFP実務の基本。\n\n【頻出】「過去の運用実績は将来を保証しない」という投資の基本原則は頻出。金融商品の選択基準として過去実績のみを重視することの問題点も理解する。\n【混同注意】過去実績は参考情報として活用できるが、選択の「唯一の基準」にはならない。コスト（信託報酬）・投資対象・リスク・運用方針等を総合的に判断することが重要。"
