"answer": 1,
"explanation": "固定利付債の名目利回りはあらかじめ確定しているため、インフレ（物価上昇）が進行すると受け取る利子の実質的な購買力が低下する。実質利回り＝名目利回り－インフレ率であるため、インフレ率が名目利回りを上回ると実質利回りはマイナスとなる（フィッシャー効果）。\n\nA：誤り。インフレ時に現金・預金の購買力が低下するのは正しいが、株式・不動産等の実物資産もインフレの影響を受ける（ただし名目価格が上昇することでインフレヘッジ効果が期待できる場合がある）。「全く受けない」という断定は誤り。\nC：誤り。物価連動国債はデフレ（物価下落）時には元本が下落する可能性があるが、一般的に「デフレフロア（元本保証）」として最低限額面100円は保証される仕組みもある。「デフレ時でも元本が必ず増加する」は誤り。\nD：誤り。金（ゴールド）はインフレヘッジとして歴史的に活用されてきたが、「必ず価格が上昇する」「唯一の資産」という断定は誤り。金価格は需給・ドル相場・リスクオフ等の様々な要因で変動する。\n\n【頻出】インフレと実質利回り（名目利回り－インフレ率）の関係、固定利付債のインフレリスクは頻出。\n【混同注意】名目利回り（額面上の数字）と実質利回り（インフレ調整後）の違いを正確に理解する。"
