"特定口座（源泉徴収あり）では、年間取引報告書が証券会社から作成され、確定申告を行わない場合でも損益通算・繰越控除は自動的に適用される",
"NISA口座では、株式・投資信託等の売却益・配当金・分配金が非課税となるが、損失が発生した場合の損益通算や繰越控除は特定口座・一般口座との間で行うことができない",
"特定口座（源泉徴収あり）の場合、証券会社が税務署への支払調書の提出を代行するため、投資家の年間取引情報が税務当局に把握されることはない"
