"退職後（60代以降）は定期的な収入がなくなるため、すべての金融資産を元本保証の預金に移換することが唯一の正解とされている",
"すべてのライフステージで、インデックスファンドへの一括投資が最も合理的な唯一の資産運用方法とされており、積立投資は非効率とされている"
