"explanation": "相続税の課税価格は、①相続・遺贈で取得した財産＋②みなし相続財産（死亡保険金・死亡退職金等）－③非課税財産－④債務・葬式費用＋⑤相続開始前7年以内（令和5年改正以前は3年）の生前贈与財産、という計算構造（相続税法第11条〜第19条）。\n\nB：誤り。被相続人の未払い入院費用は被相続人の「確実な債務」として債務控除の対象となる（相続税法第13条第1項）。\nC：誤り。相続放棄した者が受け取った死亡保険金は「みなし相続財産」として相続税の課税対象となる（相続税法第3条）。ただし相続放棄した者が受け取る保険金は非課税枠（500万円×法定相続人数）の適用がない。\nD：誤り。令和5年度改正後の生前贈与加算は、相続人だけでなく「受遺者（相続人でない者が遺贈等で財産を取得した場合）」への贈与も加算対象となる（相続税法第19条）。\n\n【頻出】課税価格の計算構造（財産＋みなし－非課税－債務葬式費用＋生前贈与）の5要素は最頻出。\n【混同注意】生前贈与加算は相続人・受遺者双方が対象（相続人のみではない）という点は近年の改正論点。"
