"explanation": "遺言執行者は遺言者の意思を実現するため必要な一切の行為をする権限を有し（民法第1012条第1項）、相続人は遺言の執行を妨げる行為をすることができず、これに違反する行為は無効となる（同法第1013条）。\n\nA：誤り。相続開始から5年以内の遺産分割禁止については、遺言者が「遺産分割を相続開始の時から5年以内の期間を定めて禁止することができる」（民法第908条）。「禁止期間は5年を超えることができない」という点は正しいが、この選択肢の文脈では「超えることができない」という制限の説明として使われており、数値自体は正しい。本問ではCが正解（answer:2）。\nB：誤り。特定遺贈があっても遺言執行者の選任は必須ではなく（家庭裁判所が選任するのは利害関係人等の請求がある場合のみ）、相続人が執行することも可能（民法第1010条）。\nD：誤り。パソコン作成の財産目録は、目録の「各ページ」に署名・押印が必要（片面のみの場合は各片面に）（民法第968条第2項）。「一つだけ署名・押印」は誤り。\n\n【頻出】遺言執行者の権限（一切の行為・相続人の妨害行為は無効）と自筆証書遺言の財産目録（各ページへの署名押印）は頻出。\n【混同注意】財産目録の「各ページに署名・押印」という要件は2019年改正の重要ポイントとして覚える。"
