"answer": 3,
"explanation": "相続時精算課税は贈与者ごとに選択するが、一度選択すると以後その贈与者からの贈与には相続時精算課税が継続適用され（撤回不可）、暦年課税に戻すことはできない（相続税法第21条の9第3項）。ただし他の贈与者からの贈与には引き続き暦年課税が適用される。\n\nA：正しい内容。相続時精算課税は贈与者ごとに選択するため、父からの贈与に選択しても、母からの贈与には別途選択する必要があり、選択していない贈与者からの贈与には暦年課税が適用される。本問ではDが正解（answer:3）。\nB：誤り。相続時精算課税を選択した贈与者からの贈与については、2024年以降は年間110万円の基礎控除が新設されたが、暦年課税の基礎控除110万円と「合算」することはできない。相続時精算課税選択後は、その贈与者からの贈与に暦年課税の基礎控除は適用されない。\nC：誤り。相続時精算課税で支払った贈与税額は、相続発生時に相続税から「控除」される（精算される）（相続税法第21条の15）。控除されないという記述は誤り。\n\n【頻出】相続時精算課税の「撤回不可・生涯継続」と、贈与者ごとの選択という特性は頻出。\n【混同注意】相続時精算課税（特定の贈与者ごとに適用・撤回不可）と暦年課税（すべての贈与者からの贈与合計に適用）の適用関係を整理。"
