"explanation": "遺産分割が変更されて相続税額が減少する場合（税額が過大となった場合）は「更正の請求」により過払い税額の還付を受けることができる（国税通則法第23条・相続税法第32条）。「更正の請求が一切認められない」という記述は誤り。逆に相続税額が増加する場合は「修正申告」が必要。\n\nA：正しい。各相続人の課税価格合計が基礎控除額を超える場合に申告義務が生じる（相続税法第27条）。\nB：正しい。申告書は連名（共同）または各自別々での提出が認められている（同条）。\nC：正しい。配偶者の税額軽減・小規模宅地等の特例等は「申告書を提出することが要件」であり、適用後の税額がゼロでも申告書の提出が必要（同法第19条の2第6項等）。\n\n【頻出】配偶者軽減・小規模宅地等の特例は「申告が要件」という点（申告しないと適用不可）、更正の請求（税額減少時）と修正申告（税額増加時）の区別は頻出。\n【混同注意】更正の請求（有利な変更→還付）と修正申告（不利な変更→追加納付）は逆の方向性。"
