"法人が受け取る死亡保険金は、資産計上していた保険料積立金と相殺された差額部分のみが益金算入となり、残額は益金不算入となる",
"経営者が死亡した際に法人が死亡保険金を受け取り、その資金を遺族への死亡退職金の支払いに充当する場合、死亡退職金の支給額は損金算入できる",
"法人が契約者・保険料負担者となる生命保険では、被保険者である経営者の死亡保険金受取人を経営者の遺族（個人）に指定することが税務上推奨されており、法人受取よりも有利な取扱いとなる"
