"answer": 2,
"explanation": "経営者が死亡した際に法人が死亡保険金を受け取り、その保険金を原資として遺族に死亡退職金（役員退職慰労金等）を支払う場合、当該死亡退職金は「不相当に高額な部分を除き」全額が損金算入できる（法人税法第34条・第36条）。これが法人保険の事業承継・資金確保における活用法の核心。\n\nA：誤り。法人が受け取った死亡保険金は法人に帰属するため、経営者の相続財産にはならない。したがって「相続税対策」としての直接効果はない（遺族は法人からの退職金として受け取る）。\nB：誤り。法人が受け取った死亡保険金は「全額が益金算入」され、資産計上していた保険料積立金等を「損金算入」することで実質的な課税所得が圧縮される仕組み。「一部益金不算入」という表現は誤り。\nD：誤り。法人が契約者・保険料負担者の場合、死亡保険金受取人を「個人（経営者の遺族）」にすると、その保険料は経営者への「給与」として課税される可能性があり、税務上必ずしも推奨されない。通常は法人が受取人となり退職金支払いの原資とする設計が一般的。\n\n【頻出】法人受取の死亡保険金→益金算入・資産計上額は損金算入、遺族への死亡退職金→損金算入、という流れは頻出の事業承継スキーム。\n【混同注意】死亡保険金（法人に帰属）と死亡退職金（遺族が受け取る）の区別、各々の税務処理を整理。"
