"explanation": "遺産分割の方法には①現物分割（各相続人に特定の財産を割り当て）、②代償分割（特定の者が取得して代わりに他の相続人に代償金を支払う）、③換価分割（遺産を売却して金銭を分配）、④共有分割（遺産を共有状態で分割）があり、相続人全員の合意があればいずれの方法でも選択できる（民法第906条等）。\n\nA：誤り。遺産分割協議は相続開始後いつでも行うことができるが、相続税の申告期限内に完了させる「法的義務」はない（申告期限内に未了でも相続権は失われない。ただし各種特例の適用に影響がある）。\nB：誤り。意思能力を欠く相続人がいる場合、その相続人を除いた協議は無効となる。成年後見人等の法定代理人を立てた上で全員参加の協議が必要（民法第3条の2・第838条等）。\nD：誤り。一度成立した遺産分割協議も、相続人全員の合意があれば解除・やり直しが可能（判例：最判平成2年9月27日等）。ただし第三者の権利等に影響する場合は制限がある。\n\n【頻出】遺産分割の4方法（現物・代償・換価・共有）と、認知症相続人への成年後見人選任の必要性は頻出。\n【混同注意】代償分割（不動産等を1人が取得→代償金支払い）と換価分割（売却→金銭分配）の違いを整理。"
