"answer": 2,
"explanation": "相次相続控除（相続税法第20条）は、今回の被相続人が過去10年以内に相続・遺贈によって財産を取得し相続税を支払っていた場合、今回の相続税額から一定割合（経過年数に応じた割合）を控除する制度。10年以内の2回以上の相続による二重課税を緩和することを目的とする。\n\nA：誤り。未成年者控除の控除額は「10万円×（18歳に達するまでの年数）」は正しいが（相続税法第19条の3）。計算年数の端数は切り上げ（1年に満たない端数は1年として計算）。\nB：誤り。障害者控除は一般障害者「10万円×（85歳まで）」は正しいが、特別障害者は「20万円×（85歳まで）」が正しい（同法第19条の4）。本問ではCが正解（answer:2）。\nD：誤り。贈与税額控除は控除しきれない場合「還付」されない（切捨て）。過払いとなった贈与税が返ってくるわけではない。ただし令和5年改正後の相続時精算課税については別途検討が必要。\n\n【頻出】相次相続控除（10年以内・前の相続税の一部控除）、未成年者控除（10万円×18歳まで）、障害者控除（一般10万円・特別20万円×85歳まで）の数値は頻出。\n【混同注意】各税額控除の対象・控除額・計算方法を一覧で整理する（外国税額控除・配偶者軽減等と混同しないこと）。"
