"explanation": "名義預金とは、口座名義人と実際の預金者（資金の拠出者・支配者）が異なる預金のこと。妻名義の預金でも夫が資金を拠出し、夫が実質的に管理・支配していた場合（妻がパスワードを知らない等）は夫の財産として相続税の課税対象となる（相続税法の実質課税の原則・判例）。\n\nB：誤り。毎年110万円の贈与でも、実際に贈与の意思表示がなく、子が存在を知らない・管理していない場合は「名義預金」として贈与の実態がないとみなされ、相続財産として課税対象となる可能性がある。「常に子の財産」にはならない場合がある。\nC：誤り。名義株式も実質的なオーナー（資金拠出者・支配者）の財産として取り扱われるべきであり、名義人が申告しても実態が伴わなければ課税上の問題が生じる可能性がある。\nD：誤り。口頭による贈与契約は法律上「有効」（民法は書面を成立要件としていない）。ただし未履行の部分は撤回可能（民法第550条）。「常に無効」は誤り。\n\n【頻出】名義預金・名義株の実質課税原則（名義よりも実態で判断）は相続税務調査での頻出論点として重要。\n【混同注意】贈与の成立要件（書面不要・口頭でも有効）と書面化の重要性（証拠として有効）を区別して理解する。"
