"Bさんが小規模企業共済に20年間加入していた場合、廃業時の共済金は退職所得として課税され、退職所得控除は適用されない",
"Bさんが国民年金基金に加入していた場合、給付は老齢基礎年金に上乗せされるが、掛金は生命保険料控除として所得控除の対象となる",
"Bさんが65歳以降も自営業を継続している場合、国民年金の第1号被保険者として保険料を納付し続けることができる"
