"answer": 1,
"explanation": "変動金利型住宅ローンには一般的に①5年ルール（金利が変動しても返済額は5年間固定）と②1.25倍ルール（返済額の増加は従前の1.25倍を上限とする）が設定されており、金利上昇時でも返済者の家計への急激な影響を抑制する仕組みとなっている。ただし未払い利息が発生するリスクもある。\n\nA：正しい内容。住宅ローン控除の床面積要件（50㎡以上）と所得上限（2,000万円以下）は正しいが本問ではBが正解（answer:1）。\nC：誤り。住宅ローン控除の初年度は「確定申告」が必要（2年目以降は給与所得者であれば年末調整で対応可）（租税特別措置法第41条）。\nD：誤り。団体信用生命保険（団信）の保険金で残債務が弁済された場合、遺族は残債務がない不動産を相続する（保険金は保険会社から直接金融機関に支払われる）。遺族が保険金を受け取るわけではないため、団信による債務弁済に対して直接相続税が課税されるわけではない。\n\n【横断ポイント】ライフプランニング（住宅ローン）×タックスプランニング（住宅ローン控除）×リスク管理（団信）の複合問題。\n【頻出】住宅ローン控除の初年度確定申告必須と、変動金利の5年ルール・1.25倍ルールは頻出。"
