"question": "Hさん（67歳・年金受給者）の収入に関する税務の記述として誤っているものはどれか。\n\nHさんの収入：老齢基礎年金（年80万円）＋老齢厚生年金（年150万円）＋賃貸マンション収入（年100万円・必要経費50万円）",
