"question": "Iさん（55歳）が相続対策と資産承継を考える場合の記述として正しいものはどれか。\n\nIさんの状況：財産総額2億円（土地5,000万円・建物2,000万円・金融資産1億3,000万円）、法定相続人：配偶者J（52歳）・子K（25歳）・子L（22歳）",
