"question": "Nさん（48歳）が投資用不動産の売却を検討している場合の税務に関する記述として正しいものはどれか。\n\nNさんの状況：賃貸マンション（取得価格5,000万円・取得から8年・売却予定価格6,000万円・取得費用100万円・売却費用200万円）",
