"explanation": "2022年4月の年金制度改正により、老齢基礎年金と老齢厚生年金はそれぞれ独立して繰下げを選択できるようになった（厚生年金保険法第44条の3・国民年金法第28条）。一方のみを繰り下げることも可能であり、「必ず同時に繰り下げなければならない」という記述は2022年4月以降の制度では誤り。\n\nA：正しい。厚生年金被保険者期間は国民年金第2号被保険者として国民年金にも同時加入しているため、厚生年金35年＋国民年金（第1号）5年＝合計40年が老齢基礎年金の算定基礎となる。\nB：正しい。60〜64歳での在職中の厚生年金加入は65歳以降の老齢厚生年金額の増加につながる（在職定時改定・退職時改定）。\nC：正しい。退職所得控除：800万円＋70万円×（35－20）＝1,850万円。退職所得：（2,500万円－1,850万円）×1/2＝325万円の計算は正しい。\n\n【横断ポイント】ライフプランニング（老後設計・年金繰下げ）×タックスプランニング（退職所得）の複合問題。\n【頻出】2022年改正による老齢基礎年金と老齢厚生年金の別々の繰下げ選択は重要改正点として頻出。"
