"category": "総合問題（全分野横断）",
"question": "Sさん（45歳・会社員）が相続対策として保険を活用する場合に関する記述として正しいものはどれか。\n\nSさんの状況：相続財産見込額3億円、法定相続人：配偶者T（43歳）・子U（18歳）・子V（15歳）",
